    //  kan Total ka waaaye
  
 $("#repotbtn").submit(function (event) {
        event.preventDefault();
    
        let student_id = $('#_student_id').val();
        let semester_id = $('#_semester_id').val();
    
        let form_data = {
            "_student_id": student_id,
            "_semester_id": semester_id,
            "action": "Total" 
        };
    
        $.ajax({
            method: "POST",
            dataType: "JSON",
            url: "../APi/resultviews.php",
            data: form_data,
            success: function (data) {
                if (data.status) {
                    let response = data.data;
                    let totalMarks = response.Total;
                    let percentage = response.Percentage;
                    let grade = response.Grade;
    
                    //   dynamic waaye 
                    $(".result_total").html(`
                        <h2>Total: ${totalMarks}</h2>
                        <h2>Percentage: ${percentage}%</h2>
                        <h2>Grade: ${grade}</h2>
                    `);
                } else {
                    console.error("Error: ", data.data);
                    $(".result_total").html("<h2>Error retrieving data.</h2>");
                }
            },
            error: function (error) {
                console.error("AJAX Error: ", error);
            }
        });
    });
    



    












