    function print_statament() {
        let studentTable = document.querySelector("#student_Table"); 
        let resultTable = document.querySelector("#resultviews_Table"); 
    
        let newwindow = window.open("");
    
        if (!newwindow) {
            alert("Please Check your Browser");
            return;
        }
    
       
        let totalMarks = 0;
        let subjectsCount = 0;
    
       
        let rows = resultTable.querySelectorAll("tr");
        rows.forEach((row, index) => {
            if (index > 0) { 
                let cells = row.querySelectorAll("td");
                let subjectTotal = parseInt(cells[5].innerText.trim());
                if (!isNaN(subjectTotal)) {
                    totalMarks += subjectTotal;
                    subjectsCount++;
                }
            }
        });
    
        let maxTotalMarks = subjectsCount * 100;
        let percentage = ((totalMarks / maxTotalMarks) * 100).toFixed(1);
        let grade = calculateGrade(percentage);
      
    
        // CSS for styling
        const styles = `
            <style>
                body {
                    font-family: Arial, sans-serif;
                    margin: 0;
                    padding: 20px;
                    background-color: #f8f9fd;
                }
    
                /* Logo Section */
                .logo {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    margin-bottom: 20px;
                }
                .logo img {
                    width: 50px;
                    height: auto;
                    margin-right: 10px;
                }
                .logo h2 {
                    color: red;
                    font-weight: bold;
                    margin: 0;
                }
                .logo h2 span {
                    color: blue;
                }
    
                /* Table Styling */
                table {
                    width: 100%;
                    border-collapse: collapse;
                    margin: 20px 0;
                    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
                }
                th, td {
                    border: 1px solid #ddd;
                    padding: 8px;
                    text-align: center;
                    background-color: #d0d2e6;
                    color: #333;
                }
                th {
                    background-color: #59baf1;
                    color: white;
                }
    
                /* Summary Section */
                .result_total {
                    background-color: #59baf1;
                    color: white;
                    padding: 15px;
                    text-align: center;
                    font-size: 16px;
                    font-weight: bold;
                    margin: 20px auto;
                    border-radius: 5px;
                    width: 300px;
                    line-height: 1.8;
                }
            </style>
        `;
   
        newwindow.document.write(`
            <html>
                <head>
                    <title>Print Report</title>
                    ${styles}
                </head>
                <body>
                    <!-- Logo Section -->
                    <div class="logo">
                        <img src="../Image/logo.png" alt="Logo">
                        <h2>HER<span>SI</span></h2>
                    </div>
    
                    <!-- Student Information Table -->
                    <table id="student_Table">
                        ${studentTable.innerHTML}
                    </table>
    
                    <!-- Marks Table -->
                    <table id="resultviews_Table">
                        ${resultTable.innerHTML}
                    </table>
    
                    <!-- Result Summary -->
                    <div class="result_total">
                        Total Marks: ${totalMarks} <br>
                        Percentage: ${percentage}% <br>
                        Grade: ${grade} <br>
                        
                    </div>
                </body>
            </html>
        `);
    
        newwindow.document.close();
        newwindow.focus();
        newwindow.print();
        newwindow.close();
    }
    //  total iyo avege ka xisaabinaa
    function calculateGrade(percentage) {
        if (percentage >= 95) return "A+";
        if (percentage >= 90) return "A";
        if (percentage >= 80) return "B";
        if (percentage >= 70) return "D";
        if (percentage >= 60) return "C";
        return "F";
    }
    

