    $('#export_statement').on('click', function () {
        let studentTable = document.querySelector("#student_Table").outerHTML;
        let resultTable = document.querySelector("#resultviews_Table");
    
     
        let totalMarks = 0;
        let subjectsCount = 0;
    
        let rows = resultTable.querySelectorAll("tr");
        rows.forEach((row, index) => {
            if (index > 0) {
                let cells = row.querySelectorAll("td");
                let subjectTotal = parseInt(cells[5].innerText.trim());
                if (!isNaN(subjectTotal)) {
                    totalMarks += subjectTotal;
                    subjectsCount++;
                }
            }
        });
    
        let maxTotalMarks = subjectsCount * 100;
        let percentage = ((totalMarks / maxTotalMarks) * 100).toFixed(1);
        let grade = calculateGrade(percentage);
    
        function calculateGrade(percentage) {
            if (percentage >= 95) return "A+";
            if (percentage >= 90) return "A";
            if (percentage >= 80) return "B";
            if (percentage >= 70) return "D";
            if (percentage >= 60) return "C";
            return "F";
        }
    
     
        let combinedHTML = `
            <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">
                <head>
                    <meta charset="utf-8" />
                    <style>
                        table {
                            border-collapse: collapse;
                            width: 100%;
                        }
                        th, td {
                            border: 1px solid black;
                            padding: 8px;
                            text-align: center;
                        }
                        th {
                            background-color: #f2f2f2;
                        }
                        .summary {
                            margin-top: 20px;
                            font-size: 16px;
                            font-weight: bold;
                        }
                    </style>
                </head>
                <body>
                    <h2>Student Information</h2>
                    ${studentTable}
                    <h2>Results</h2>
                    ${resultTable.outerHTML}
                    <div class="summary">
                        Total Marks: ${totalMarks} <br>
                        Maximum Marks: ${maxTotalMarks} <br>
                        Percentage: ${percentage}% <br>
                        Grade: ${grade}
                    </div>
                </body>
            </html>
        `;
 
        let file = new Blob([combinedHTML], { type: "application/vnd.ms-excel" });
    
        let url = URL.createObjectURL(file);
        let a = document.createElement("a");
        a.href = url;
        a.download = "combined_statement.xls";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    });
    
    